const config = {
  "previewFeatures": [],
  "clientVersion": "7.4.2",
  "engineVersion": "94a226be1cf2967af2541cca5529f0f7ba866919",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============================================\n// USERS & AUTH\n// ============================================\n\nmodel User {\n  id       String  @id @default(cuid())\n  name     String\n  email    String  @unique\n  password String\n  phone    String?\n  role     Role    @default(USER)\n\n  status     RecordStatus @default(ACTIVE)\n  archivedAt DateTime?\n\n  lastLogin DateTime?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @default(now()) @updatedAt\n\n  customer Customer?\n\n  movements      Movement[]\n  purchaseOrders Order[]\n  saleOrders     SaleOrder[] @relation(\"SaleOrderCustomer\")\n  soldOrders     SaleOrder[] @relation(\"SaleOrderSeller\")\n  receipts       Receipt[]\n  auditLogs      AuditLog[]\n\n  @@index([status])\n  @@map(\"users\")\n}\n\nenum Role {\n  ADMIN // Acceso total\n  USER // Solicitar pedidos, ver historial\n  WAREHOUSE // Gestionar inventario, recibir pedidos\n  SELLER // Vender, crear pedidos de venta\n}\n\nenum RecordStatus {\n  ACTIVE\n  INACTIVE\n  ARCHIVED\n}\n\n// ============================================\n// CUSTOMERS (Para ventas minorista/mayorista)\n// ============================================\n\nmodel Customer {\n  id           String       @id @default(cuid())\n  name         String\n  email        String?      @unique\n  phone        String?\n  document     String?\n  customerType CustomerType @default(RETAIL)\n\n  status     RecordStatus @default(ACTIVE)\n  archivedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  userId String? @unique\n  user   User?   @relation(fields: [userId], references: [id])\n\n  saleOrders SaleOrder[]\n\n  @@index([status])\n  @@map(\"customers\")\n}\n\nenum CustomerType {\n  RETAIL // Minorista\n  WHOLESALE // Mayorista\n}\n\n// ============================================\n// INVENTORY CONFIGURATION\n// ============================================\n\nmodel Category {\n  id          String  @id @default(cuid())\n  name        String\n  description String?\n\n  status     RecordStatus @default(ACTIVE)\n  archivedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  products Product[]\n\n  @@index([status])\n  @@map(\"categories\")\n}\n\nmodel Supplier {\n  id      String  @id @default(cuid())\n  name    String\n  contact String?\n  email   String?\n  phone   String?\n  address String?\n\n  status     RecordStatus @default(ACTIVE)\n  archivedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  products Product[]\n  orders   Order[] // Purchase orders\n\n  @@index([status])\n  @@map(\"suppliers\")\n}\n\nmodel UnitOfMeasure {\n  id     String  @id @default(cuid())\n  name   String  @unique\n  symbol String?\n\n  status     RecordStatus @default(ACTIVE)\n  archivedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  products Product[]\n\n  @@index([status])\n  @@map(\"units_of_measure\")\n}\n\n// ============================================\n// PRODUCTS & PRICING TIERS\n// ============================================\n\nmodel Product {\n  id            String  @id @default(cuid())\n  code          String  @unique // 🔲 Código de barras / SKU\n  name          String\n  description   String?\n  image         String? // URL de la imagen principal\n  purchasePrice Decimal @db.Decimal(10, 2)\n\n  // Precios base\n  retailPrice          Decimal  @db.Decimal(10, 2) // Precio minorista (1 unidad)\n  wholesalePrice       Decimal? @db.Decimal(10, 2) // Precio mayorista (aplica si quantity >= wholesaleMinQuantity)\n  wholesaleMinQuantity Int      @default(10) // Cantidad mínima para precio mayorista\n\n  // Límites de venta\n  minSalePrice Decimal? @db.Decimal(10, 2)\n  maxSalePrice Decimal? @db.Decimal(10, 2)\n\n  // Stock\n  minStock      Int @default(0)\n  currentStock  Int @default(0)\n  reservedStock Int @default(0) // Stock reservado en pedidos pendientes\n\n  status     RecordStatus @default(ACTIVE)\n  archivedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  // Relaciones\n  categoryId String\n  category   Category @relation(fields: [categoryId], references: [id])\n\n  supplierId String?\n  supplier   Supplier? @relation(fields: [supplierId], references: [id])\n\n  unitId String\n  unit   UnitOfMeasure @relation(fields: [unitId], references: [id])\n\n  movements            Movement[]\n  purchaseOrderDetails OrderDetail[]\n  saleOrderDetails     SaleOrderDetail[]\n\n  recommendationsFrom ProductRecommendation[] @relation(\"ProductRecommendationsFrom\")\n  recommendationsTo   ProductRecommendation[] @relation(\"ProductRecommendationsTo\")\n\n  @@index([status])\n  @@index([code]) // 🔲 Índice para búsqueda rápida por código de barras\n  @@index([categoryId])\n  @@index([supplierId])\n  @@map(\"products\")\n}\n\nmodel ProductRecommendation {\n  id                   String   @id @default(cuid())\n  productId            String\n  recommendedProductId String\n  priority             Int      @default(0)\n  createdAt            DateTime @default(now())\n\n  product            Product @relation(\"ProductRecommendationsFrom\", fields: [productId], references: [id], onDelete: Cascade)\n  recommendedProduct Product @relation(\"ProductRecommendationsTo\", fields: [recommendedProductId], references: [id], onDelete: Cascade)\n\n  @@unique([productId, recommendedProductId])\n  @@index([productId])\n  @@index([recommendedProductId])\n  @@map(\"product_recommendations\")\n}\n\n// ============================================\n// MOVEMENTS (AUDITORÍA DE INVENTARIO)\n// ============================================\n\nmodel Movement {\n  id          String       @id @default(cuid())\n  type        MovementType\n  quantity    Int\n  stockBefore Int\n  stockAfter  Int\n  reason      String?\n  unitPrice   Decimal?     @db.Decimal(10, 2)\n  reference   String? // ID de orden, factura, etc.\n  createdAt   DateTime     @default(now())\n\n  productId String\n  product   Product @relation(fields: [productId], references: [id])\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id])\n\n  @@index([productId])\n  @@index([userId])\n  @@index([createdAt])\n  @@map(\"movements\")\n}\n\nenum MovementType {\n  IN // Entrada por compra\n  OUT // Salida por venta\n  ADJUSTMENT // Ajuste manual\n  RETURN // Devolución\n  RESERVE // Reservar stock para pedido\n  RELEASE // Liberar stock reservado\n}\n\n// ============================================\n// PURCHASE ORDERS (Pedidos a Proveedores)\n// ============================================\n\nmodel Order {\n  id                   String      @id @default(cuid())\n  orderNumber          String      @unique // Ej: PO-2026-00123\n  status               OrderStatus @default(PENDING)\n  total                Decimal     @default(0) @db.Decimal(12, 2)\n  orderDate            DateTime    @default(now())\n  expectedDeliveryDate DateTime?\n  receivedDate         DateTime?\n  observations         String?\n  createdAt            DateTime    @default(now())\n\n  supplierId String\n  supplier   Supplier @relation(fields: [supplierId], references: [id])\n\n  userId String // Usuario que creó el pedido\n  user   User   @relation(fields: [userId], references: [id])\n\n  details  OrderDetail[]\n  receipts Receipt[] // Comprobantes de pago/facturas\n\n  @@map(\"orders\")\n}\n\nenum OrderStatus {\n  DRAFT // Borrador\n  PENDING // Enviado a aprobación\n  APPROVED // Aprobado por admin\n  RECEIVED // Recibido en almacén (stock actualizado)\n  CANCELLED // Cancelado\n}\n\nmodel OrderDetail {\n  id       String  @id @default(cuid())\n  quantity Int\n  price    Decimal @db.Decimal(10, 2) // Precio de compra unitario\n  subtotal Decimal @db.Decimal(12, 2)\n\n  orderId String\n  order   Order  @relation(fields: [orderId], references: [id], onDelete: Cascade)\n\n  productId String\n  product   Product @relation(fields: [productId], references: [id])\n\n  @@map(\"order_details\")\n}\n\n// ============================================\n// SALE ORDERS (Pedidos de Clientes - Ventas)\n// ============================================\n\nmodel SaleOrder {\n  id          String          @id @default(cuid())\n  orderNumber String          @unique // Ej: SO-2026-00123\n  status      SaleOrderStatus @default(PENDING_REQUEST)\n\n  // Tipo de cliente y precios aplicados\n  customerType   CustomerType\n  pricingApplied PricingType // RETAIL o WHOLESALE (calculado al crear)\n\n  total         Decimal   @default(0) @db.Decimal(12, 2)\n  orderDate     DateTime  @default(now())\n  deliveryDate  DateTime?\n  completedDate DateTime?\n  observations  String?\n  createdAt     DateTime  @default(now())\n\n  // Cliente (puede ser User registrado o Customer externo)\n  userId String?\n  user   User?   @relation(\"SaleOrderCustomer\", fields: [userId], references: [id])\n\n  customerId String? // Si es cliente externo\n  customer   Customer? @relation(fields: [customerId], references: [id])\n\n  // Vendedor asignado\n  // ✅ Vendedor (quien atiende el pedido) - Relación nombrada\n  sellerId String?\n  seller   User?   @relation(\"SaleOrderSeller\", fields: [sellerId], references: [id])\n\n  details   SaleOrderDetail[]\n  receipts  Receipt[] // Comprobantes de pago (fotos)\n  auditLogs AuditLog[]\n\n  @@index([userId])\n  @@index([customerId])\n  @@index([status])\n  @@map(\"sale_orders\")\n}\n\nenum SaleOrderStatus {\n  PENDING_REQUEST // 🟡 Usuario solicitó (espera aprobación)\n  APPROVED // 🟢 Admin aprobó (reserva stock)\n  PREPARING // 📦 En preparación\n  READY // ✅ Listo para retirar/enviar\n  COMPLETED // 🎉 Entregado y finalizado\n  CANCELLED // ❌ Cancelado por usuario o admin\n  REJECTED // ⛔ Rechazado por admin (sin stock, etc.)\n}\n\nenum PricingType {\n  RETAIL // Precio minorista\n  WHOLESALE // Precio mayorista (aplica por cantidad)\n}\n\nmodel SaleOrderDetail {\n  id        String  @id @default(cuid())\n  quantity  Int\n  unitPrice Decimal @db.Decimal(10, 2) // Precio aplicado (retail/wholesale)\n  subtotal  Decimal @db.Decimal(12, 2)\n\n  // Para auditoría: precios originales del producto\n  productSnapshot Json? // Copia del producto al momento de la venta\n\n  orderId String\n  order   SaleOrder @relation(fields: [orderId], references: [id], onDelete: Cascade)\n\n  productId String\n  product   Product @relation(fields: [productId], references: [id])\n\n  @@map(\"sale_order_details\")\n}\n\n// ============================================\n// RECEIPTS / COMPROBANTES (FOTOS)\n// ============================================\n\nmodel Receipt {\n  id         String      @id @default(cuid())\n  type       ReceiptType\n  fileUrl    String // URL o path en storage (S3, Cloudinary, local)\n  fileName   String\n  fileSize   Int // En bytes\n  mimeType   String\n  uploadedAt DateTime    @default(now())\n\n  // 🔒 Validación para evitar llenar la BD\n  deleted        Boolean   @default(false) // Soft delete\n  deletedAt      DateTime?\n  deletionReason String? // Motivo de eliminación (auditoría)\n  autoDeleteAt   DateTime? // Fecha programada para eliminación automática\n\n  // Relaciones polimórficas simplificadas\n  orderId String? // Para purchase orders\n  order   Order?  @relation(fields: [orderId], references: [id])\n\n  saleOrderId String? // Para sale orders\n  saleOrder   SaleOrder? @relation(fields: [saleOrderId], references: [id])\n\n  uploadedById String\n  uploadedBy   User   @relation(fields: [uploadedById], references: [id])\n\n  @@index([orderId])\n  @@index([saleOrderId])\n  @@index([deleted])\n  @@map(\"receipts\")\n}\n\nenum ReceiptType {\n  INVOICE // Factura de compra\n  PAYMENT_PROOF // Comprobante de pago (foto)\n  DELIVERY_PROOF // Foto de entrega\n  OTHER\n}\n\n// ============================================\n// AUDIT LOG / HISTORIAL\n// ============================================\n\nmodel AuditLog {\n  id         String   @id @default(cuid())\n  action     String // CREATE, UPDATE, DELETE, APPROVE, CANCEL\n  entityType String // \"SaleOrder\", \"Product\", etc.\n  entityId   String // ID del registro afectado\n  changes    Json? // { before: {}, after: {} }\n  ipAddress  String?\n  userAgent  String?\n  createdAt  DateTime @default(now())\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id])\n\n  // Relación opcional con SaleOrder para historial específico\n  saleOrderId String?\n  saleOrder   SaleOrder? @relation(fields: [saleOrderId], references: [id])\n\n  @@index([entityType, entityId])\n  @@index([userId])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n\n// ============================================\n// MIDDLEWARE CONFIG (Opcional para rutas)\n// ============================================\n\nmodel RoutePermission {\n  id     String @id @default(cuid())\n  route  String @unique // Ej: \"/dashboard/orders/approve\"\n  method String @default(\"GET\") // GET, POST, PUT, DELETE\n  roles  Role[] // Roles permitidos\n\n  status     RecordStatus @default(ACTIVE)\n  archivedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([status])\n  @@map(\"route_permissions\")\n}\n"
}

